import { ColumnDef, Row } from '@tanstack/react-table';
import user from '@/assets/imgs/user.png';
import ViewIcon from '@/components/icons/ViewIcon';
import { Attendances } from '../../types/attendances.types';
import { Link } from 'react-router-dom';
import { cn } from '@/lib/utils';

function formatTime(value?: string | null) {
    if (!value) return null;

    // Common backend formats: "HH:mm:ss" or full ISO datetime.
    // We only want HH:mm.
    const asString = String(value);
    const timePart = asString.includes('T') ? asString.split('T')[1] : asString;
    const hhmmss = timePart.split('.')[0]; // drop ms if any

    // "09:30:00" -> "09:30"
    if (/^\d{2}:\d{2}:\d{2}$/.test(hhmmss)) return hhmmss.slice(0, 5);
    // "09:30" already
    if (/^\d{2}:\d{2}$/.test(hhmmss)) return hhmmss;

    return hhmmss;
}

// Create a separate component for the actions cell
const ActionsCell = ({ row }: { row: Row<Attendances> }) => {
    return (
        <div className="cursor-pointer flex justify-center">
            <Link to={`/human-resources/employee/${row.original?.id}/attendance`}>
                <ViewIcon className="text-primery-blue-400" />
            </Link>
        </div>
    );
};

export const columns: ColumnDef<Attendances>[] = [
    {
        accessorKey: 'id',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    اسم الموظف
                </div>
            );
        },
        cell: ({ row }) => (
            <div className="flex flex-row justify-start items-center gap-4 text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                <img src={user} alt="" className="rounded-full w-10 h-10 object-cover" />
                <div className="flex flex-col gap-1">
                    <p className="tracking-normal text-primery-blue-900 font-medium text-sm">{row.original?.name}</p>
                    <p className="tracking-normal text-white-blue-800 font-normal text-sm">
                        {`${row.original?.position}`}
                    </p>
                </div>
            </div>
        ),
    },
    {
        accessorKey: 'name',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    كود الموظف
                </div>
            );
        },
        cell: ({ row }) => (
            <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                {row.original?.id}
            </div>
        ),
    },
    {
        accessorKey: 'status',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    الفرع
                </div>
            );
        },
        cell: ({ row }) => {
            return (
                <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                    {row.original?.branch?.name}
                </div>
            );
        },
    },
    {
        accessorKey: 'attendance_type',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    نوع الحضور
                </div>
            );
        },
        cell: ({ row }) => {
            const type = row.original?.attendance_type || row.original?.status;
            const labelMap: Record<string, string> = {
                present: 'حاضر',
                late: 'متأخر',
                absent: 'غائب',
                leave: 'إذن',
                holiday: 'إجازة',
                vacation: 'إجازة',
            };
            const label = type ? labelMap[type] || type : '—';

            const variantClass =
                type === 'present'
                    ? 'bg-green-50 text-green-700 border-green-200'
                    : type === 'late'
                      ? 'bg-amber-50 text-amber-700 border-amber-200'
                      : type === 'absent'
                        ? 'bg-red-50 text-red-700 border-red-200'
                        : 'bg-white-blue-50 text-white-blue-800 border-white-blue-200';

            return (
                <div className="px-4 py-3">
                    <span className={cn('inline-flex items-center rounded-full border px-3 py-1 text-xs font-semibold', variantClass)}>
                        {label}
                    </span>
                </div>
            );
        },
    },
    {
        accessorKey: 'check_in',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    وقت الدخول
                </div>
            );
        },
        cell: ({ row }) => {
            const t = formatTime(row.original?.shift.shift_start_time);
            return (
                <div
                    className={cn('text-sm px-4 py-3 leading-[26.24px] font-semibold tracking-normal', {
                        '!text-primery-blue-500': Boolean(t),
                        'text-[#A1A1AA] font-normal': !t,
                    })}
                >
                    {t ?? '—'}
                </div>
            );
        },
    },
    {
        accessorKey: 'check_out',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    وقت الخروج
                </div>
            );
        },
        cell: ({ row }) => {
            const t = formatTime(row.original?.shift.shift_end_time);
            return (
                <div
                    className={cn('text-sm px-4 py-3 leading-[26.24px] font-semibold tracking-normal', {
                        '!text-primery-blue-500': Boolean(t),
                        'text-[#A1A1AA] font-normal': !t,
                    })}
                >
                    {t ?? '—'}
                </div>
            );
        },
    },
    {
        id: 'actions',
        header: () => {
            return (
                <div className="text-sm text-center px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    التقرير
                </div>
            );
        },
        cell: ({ row }) => <ActionsCell row={row} />,
    },
];
